package com.procurement.purchaseorder.controller;import com.procurement.common.response.*;import com.procurement.purchaseorder.dto.request.*;import com.procurement.purchaseorder.dto.response.*;import com.procurement.purchaseorder.entity.*;import com.procurement.purchaseorder.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/purchase-orders")public class PurchaseOrderController{private final PurchaseOrderService s;public PurchaseOrderController(PurchaseOrderService s){this.s=s;}private Pageable p(int a,int b,String c,String d){return PageRequest.of(a,b,Sort.by(Sort.Direction.fromString(d),c));}@PostMapping @PreAuthorize("hasAuthority('CAN_CREATE_PO')")public ResponseEntity<ApiResponse<PurchaseOrderResponse>>create(@Valid@RequestBody PurchaseOrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Purchase order generated",s.generate(r.quotationComparisonId(),r)));}@PostMapping("/generate/{comparisonId}")@PreAuthorize("hasAuthority('CAN_CREATE_PO')")public ResponseEntity<ApiResponse<PurchaseOrderResponse>>generate(@PathVariable Long comparisonId,@Valid@RequestBody PurchaseOrderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Purchase order generated",s.generate(comparisonId,r)));}@GetMapping public ApiResponse<PageResponse<PurchaseOrderResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long vendorId,@RequestParam(required=false)PurchaseOrderStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="orderDate")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(s.search(keyword,vendorId,status,p(page,size,sort,direction)));}@GetMapping("/search")public ApiResponse<PageResponse<PurchaseOrderResponse>>alias(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long vendorId,@RequestParam(required=false)PurchaseOrderStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="orderDate")String sort,@RequestParam(defaultValue="desc")String direction){return search(keyword,vendorId,status,page,size,sort,direction);}@GetMapping("/by-request/{purchaseRequestId}")public ApiResponse<PageResponse<PurchaseOrderResponse>>byRequest(@PathVariable Long purchaseRequestId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="5")int size){return ApiResponse.success(s.searchByRequest(purchaseRequestId,PageRequest.of(page,size)));}@GetMapping("/{id}")public ApiResponse<PurchaseOrderResponse>get(@PathVariable Long id){return ApiResponse.success(s.get(id));}@PutMapping("/{id}")public ApiResponse<PurchaseOrderResponse>update(@PathVariable Long id,@Valid@RequestBody PurchaseOrderRequest r){return ApiResponse.success("Purchase order updated",s.update(id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/send")public ApiResponse<PurchaseOrderResponse>send(@PathVariable Long id){return ApiResponse.success("Purchase order sent",s.send(id));}@PostMapping("/{id}/acknowledge")public ApiResponse<PurchaseOrderResponse>ack(@PathVariable Long id){return ApiResponse.success("Purchase order acknowledged",s.acknowledge(id));}@PostMapping("/{id}/cancel")public ApiResponse<PurchaseOrderResponse>cancel(@PathVariable Long id){return ApiResponse.success("Purchase order cancelled",s.cancel(id));}@PostMapping("/{id}/close")public ApiResponse<PurchaseOrderResponse>close(@PathVariable Long id){return ApiResponse.success("Purchase order closed",s.close(id));}@PostMapping("/{id}/attachments")public ResponseEntity<ApiResponse<PurchaseOrderAttachmentResponse>>attachment(@PathVariable Long id,@Valid@RequestBody PurchaseOrderAttachmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Attachment added",s.attachment(id,r)));}@GetMapping("/{id}/attachments")public ApiResponse<PageResponse<PurchaseOrderAttachmentResponse>>attachments(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.attachments(id,p(page,size,"uploadedAt","desc")));}@DeleteMapping("/{id}/attachments/{attachmentId}")public ResponseEntity<Void>deleteAttachment(@PathVariable Long id,@PathVariable Long attachmentId){s.deleteAttachment(id,attachmentId);return ResponseEntity.noContent().build();}@GetMapping("/{id}/history")public ApiResponse<PageResponse<PurchaseOrderHistoryResponse>>history(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.history(id,p(page,size,"performedAt","asc")));}}
